import React, { useState, useEffect } from 'react';
import logoImg from './logo.png';

function App() {
  // Controle de Navegação Interna
  // 'dashboard', 'bpm', 'sono', 'estresse', 'recomendacoes', 'agendar', 'emergencia', 'atividade'
  const [currentPage, setCurrentPage] = useState('dashboard');

  const [appointments, setAppointments] = useState([]);
  const [healthUnits, setHealthUnits] = useState([]);
  const [loading, setLoading] = useState(true);

  // Estados de Interação do Usuário
  const [userStressText, setUserStressText] = useState('');
  const [userMood, setUserMood] = useState('Calmo');
  const [aiStressFeedback, setAiStressFeedback] = useState(null);

  const [isSharingBpm, setIsSharingBpm] = useState(false);
  const [newAppointment, setNewAppointment] = useState({ tipo: 'Unidade Móvel', local: 'Rede Credenciada', data: '', hora: '' });

  // Estado para o Módulo de Atividade Física
  const [activeActivity, setActiveActivity] = useState(null); // 'Caminhada', 'Corrida', 'Ciclismo'
  const [activityStats, setActivityStats] = useState({ passos: 0, distancia: 0, velocidade: 0, velMedia: 0, relevo: 'Plano' });
  const [activityInterval, setActivityInterval] = useState(null);

  const [healthMetrics] = useState({
    bpm: 76,
    sono: "7h 20m",
    estresse: "Normal",
    recomendacoes: "Análise Ativa",
    iaRecommendation: "Seu nível de estresse reduziu 12% após a melhoria do sono. Excelente evolução! Continue mantendo a hidratação constante durante as rotas externas hoje."
  });

  // Dados históricos dos últimos 7 dias (Métricas Ativas)
  const historyData = {
    bpm: [72, 75, 78, 82, 74, 76, 76],
    sono: [6.5, 7.0, 5.8, 7.2, 6.8, 7.3, 7.3],
    apineias: [1, 0, 2, 4, 1, 0, 1], // Ocorrências de apineia por noite
    estresse: [20, 35, 55, 75, 40, 25, 20],
    dias: ['Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom', 'Seg']
  };

  useEffect(() => {
    Promise.all([
      fetch('http://localhost:8000/appointments').then(res => res.json()),
      fetch('http://localhost:8000/health-units').then(res => res.json())
    ])
    .then(([appointmentsData, unitsData]) => {
      setAppointments(appointmentsData);
      setHealthUnits(unitsData);
      setLoading(false);
    })
    .catch((err) => {
      console.error("Erro ao conectar com a API do Back-end:", err);
      setLoading(false);
    });
  }, []);

  // Processa Diário de Estresse com cruzamento de IA Inteligente
  const handleStressSubmit = (e) => {
    e.preventDefault();
    if (!userStressText.trim()) return;

    // Simulação de cruzamento de dados feito pela IA (Histórico + Sono + Rotina)
    setAiStressFeedback({
      analise: `Identificamos que seu estado (${userMood}) coincide com uma noite de sono anterior de 7.3h. Cruzando com seu histórico médico de prontuário e as flutuações de batimentos cardíacos (média 76 BPM), a IA sugere evitar cafeína após as 16h hoje.`,
      sugestoes: [
        "Prática Saudável: 10 minutos de meditação guiada focada na respiração diafragmática.",
        "Atividade ao Ar Livre: Uma caminhada leve de 20 minutos no fim da tarde para regulação do cortisol.",
        "Ajuste de Rotina: Pausa ativa de 5 minutos a cada 2 horas de trabalho contínuo."
      ]
    });
    setUserStressText('');
  };

  // Executa o Agendamento de Consulta Expandido
  const handleScheduleSubmit = (e) => {
    e.preventDefault();
    if (!newAppointment.data || !newAppointment.hora) {
      alert("Por favor, preencha todos os campos de data e horário.");
      return;
    }
    const createdAppointment = {
      id: appointments.length + 1,
      patient_name: "Eduardo Luz",
      appointment_type: `${newAppointment.tipo} (${newAppointment.local})`,
      date_time: `${newAppointment.data} às ${newAppointment.hora}`,
      status: "Agendado"
    };
    setAppointments([createdAppointment, ...appointments]);
    alert(`Consulta agendada com sucesso para: ${newAppointment.local}!`);
    setCurrentPage('dashboard');
  };

  // Inicia os contadores da Atividade Física em tempo real
  const startPhysicalActivity = (type) => {
    if (activityInterval) clearInterval(activityInterval);
    setActiveActivity(type);
    setActivityStats({ passos: 0, distancia: 0, velocidade: 0, velMedia: 0, relevo: 'Plano' });

    let count = 0;
    const interval = setInterval(() => {
      count++;
      setActivityStats(prev => {
        const novosPassos = type === 'Ciclismo' ? 0 : prev.passos + Math.floor(Math.random() * 3) + 1;
        const velAtual = type === 'Corrida' ? 10 + Math.random() : type === 'Ciclismo' ? 18 + Math.random() : 4 + Math.random();
        const distNova = prev.distancia + (velAtual / 3600); // Acumula distância por segundo
        const relevos = ['Plano', 'Leve Aclive', 'Plano', 'Declive Irregular'];

        return {
          passos: novosPassos,
          distancia: parseFloat(distNova.toFixed(3)),
          velocidade: parseFloat(velAtual.toFixed(1)),
          velMedia: parseFloat(((prev.velMedia * (count - 1) + velAtual) / count).toFixed(1)),
          relevo: relevos[Math.floor(Math.random() * relevos.length)]
        };
      });
    }, 1000);
    setActivityInterval(interval);
  };

  const stopPhysicalActivity = () => {
    if (activityInterval) {
      clearInterval(activityInterval);
      setActivityInterval(null);
    }
    alert(`Atividade de ${activeActivity} salva no seu histórico com sucesso! Total percorrido: ${activityStats.distancia} km.`);
    setActiveActivity(null);
  };

  return (
    <div style={styles.body}>
      {/* Top Navbar */}
      <header style={styles.navbar}>
        <div style={styles.brandContainer} onClick={() => setCurrentPage('dashboard')}>
          <div style={styles.logoContainer}>
            <img src={logoImg} alt="Logo Saúde Para Todos" style={styles.logoImage} />
          </div>
          <h1 style={styles.navTitle}>Saúde Para Todos</h1>
        </div>
        <div style={styles.navLinks}>
          <span style={styles.userBadge}>Ecossistema Integrado</span>
          {currentPage !== 'dashboard' && (
            <button style={styles.backButton} onClick={() => setCurrentPage('dashboard')}>⬅ Voltar ao Painel</button>
          )}
        </div>
      </header>

      <div style={styles.mainContainer}>

        {/* VIEW 1: DASHBOARD PRINCIPAL */}
        {currentPage === 'dashboard' && (
          <>
            <section style={styles.leftColumn}>
              <div style={styles.iaCard}>
                <div style={styles.iaHeader}>
                  <span style={{ fontSize: '20px' }}>✨</span>
                  <h3 style={styles.iaTitle}>Recomendações Personalizadas de IA</h3>
                </div>
                <p style={styles.iaText}>{healthMetrics.iaRecommendation}</p>
              </div>

              {/* Módulo Health Sync Expandido */}
              <h2 style={styles.sectionHeading}>Saúde Para Todos — Métricas Ativas (Clique para Abrir)</h2>
              <div style={styles.metricsGrid}>

                {/* 1. Batimentos */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('bpm')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#e53e3e" }}>❤️</span>
                    <span style={styles.metricLabel}>Batimentos Cardíacos</span>
                  </div>
                  <p style={styles.metricValue}>{healthMetrics.bpm} <span style={styles.metricUnit}>BPM</span></p>
                  <span style={styles.metricStatusStable}>Monitoramento & Compartilhamento ➔</span>
                </div>

                {/* 2. Sono */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('sono')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#3182ce" }}>🌙</span>
                    <span style={styles.metricLabel}>Monitoramento do Sono</span>
                  </div>
                  <p style={styles.metricValue}>{healthMetrics.sono}</p>
                  <span style={styles.metricStatusStable}>Qualidade, Horas & Apneias ➔</span>
                </div>

                {/* 3. Estresse */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('estresse')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#dd6b20" }}>⚡</span>
                    <span style={styles.metricLabel}>Nível de Estresse</span>
                  </div>
                  <p style={styles.metricValue}>{healthMetrics.estresse}</p>
                  <span style={styles.metricStatusStable}>Diário de Espírito & Cruzamento ➔</span>
                </div>

                {/* 4. Recomendações */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('recomendacoes')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#319795" }}>📜</span>
                    <span style={styles.metricLabel}>Recomendações</span>
                  </div>
                  <p style={styles.metricValue}>Estilo de Vida</p>
                  <span style={styles.metricStatusStable}>Prontuário & Relatórios IA ➔</span>
                </div>

                {/* 5. Agendar Consulta */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('agendar')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#4a5568" }}>✍️</span>
                    <span style={styles.metricLabel}>Agendar Consulta</span>
                  </div>
                  <p style={styles.metricValue}>Rede Integrada</p>
                  <span style={styles.metricStatusStable}>Móvel, UBS & Telemedicina ➔</span>
                </div>

                {/* 6. Atividade Física */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('atividade')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#38a169" }}>🏃‍♂️</span>
                    <span style={styles.metricLabel}>Atividade Física</span>
                  </div>
                  <p style={styles.metricValue}>Mapeamento</p>
                  <span style={styles.metricStatusStable}>Passos, Velocidade & Relevo ➔</span>
                </div>

                {/* 7. Emergência */}
                <div style={{...styles.clickableCard, borderColor: '#feb2b2'}} onClick={() => setCurrentPage('emergencia')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#e53e3e" }}>🚨</span>
                    <span style={styles.metricLabel}>Emergência</span>
                  </div>
                  <p style={styles.metricValue}>Contatos Úteis</p>
                  <span style={styles.metricStatusEmergency}>Números Diretos ➔</span>
                </div>

              </div>
            </section>

            <section style={styles.rightColumn}>
              <h2 style={styles.sectionHeading}>Unidades Móveis e Postos Ativos</h2>
              <div style={styles.unitsList}>
                {loading ? <p>Carregando unidades...</p> : healthUnits.map(unit => (
                  <div key={unit.id} style={styles.unitItem}>
                    <div>
                      <h4 style={styles.unitName}>🚐 {unit.name}</h4>
                      <p style={styles.unitLocation}>{unit.location}</p>
                    </div>
                    <span style={styles.activeBadge}>{unit.status}</span>
                  </div>
                ))}
              </div>

              <h2 style={styles.sectionHeading}><br/>Consultas Marcadas e Triagens</h2>
              <div style={styles.tableWrapper}>
                <table style={styles.table}>
                  <thead>
                    <tr style={styles.tableHeaderRow}>
                      <th style={styles.tableTh}>Paciente</th>
                      <th style={styles.tableTh}>Atendimento / Rede</th>
                      <th style={styles.tableTh}>Data/Hora</th>
                      <th style={styles.tableTh}>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {appointments.map((app) => (
                      <tr key={app.id} style={styles.tableRow}>
                        <td style={styles.patientNameTd}>{app.patient_name}</td>
                        <td style={styles.tableTd}>{app.appointment_type}</td>
                        <td style={styles.tableTd}>{app.date_time}</td>
                        <td style={styles.tableTd}><span style={styles.statusPill}>{app.status}</span></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>
          </>
        )}

        {/* PÁGINA 1: BATIMENTOS CARDÍACOS */}
        {currentPage === 'bpm' && (
          <div style={styles.fullWidthView}>
            <div style={styles.viewHeader}>
              <h2>❤️ Monitoramento de Frequência Cardíaca Ativa</h2>
              <button
                style={{...styles.actionBtn, backgroundColor: isSharingBpm ? '#e53e3e' : '#2b9393'}}
                onClick={() => setIsSharingBpm(!isSharingBpm)}
              >
                {isSharingBpm ? '🛑 Interromper Compartilhamento' : '📡 Compartilhar em Tempo Real com Médico'}
              </button>
            </div>

            <p>Seus dados estão sendo transmitidos via ecossistema seguro. Abaixo, acompanhe a oscilação dos últimos 7 dias:</p>
            {isSharingBpm && <div style={styles.liveAlert}>🟢 Transmissão Ativa: Seu cardiologista do ecossistema Saúde Para Todos possui acesso síncrono.</div>}

            <div style={styles.chartContainer}>
              {historyData.bpm.map((value, i) => (
                <div key={i} style={styles.chartBarWrapper}>
                  <div style={{...styles.chartBar, height: `${value * 2}px`, backgroundColor: '#e53e3e'}} />
                  <span style={styles.chartBarLabel}>{value} BPM</span>
                  <span style={styles.chartBarDay}>{historyData.dias[i]}</span>
                </div>
              ))}
            </div>

            <div style={styles.iaCard}>
              <h4>🤖 Relatório Gerado por IA (Cardio-Análise)</h4>
              <p style={{margin: 0}}>Variabilidade de frequência cardíaca dentro dos parâmetros ideais de repouso. Pequena elevação na quinta-feira condizente com estresse de rotas externas prolongadas. Nenhuma arritmia ou extrassístole detectada nas últimas 168 horas.</p>
            </div>
          </div>
        )}

        {/* PÁGINA 2: MONITORAMENTO DO SONO */}
        {currentPage === 'sono' && (
          <div style={styles.fullWidthView}>
            <h2>🌙 Monitoramento Clínico do Sono & Distúrbios</h2>
            <p>Análise voltada para detecção precoce de insônias e apineias obstrutivas, auxiliando diagnósticos e futuros tratamentos médicos.</p>

            <div style={styles.chartContainer}>
              {historyData.sono.map((value, i) => (
                <div key={i} style={styles.chartBarWrapper}>
                  <div style={{...styles.chartBar, height: `${value * 22}px`, backgroundColor: '#3182ce'}} />
                  <span style={styles.chartBarLabel}>{value}h</span>
                  <span style={{...styles.chartBarLabel, color: historyData.apineias[i] > 2 ? '#e53e3e' : '#718096'}}>
                    ⚠️ Apineias: {historyData.apineias[i]}
                  </span>
                  <span style={styles.chartBarDay}>{historyData.dias[i]}</span>
                </div>
              ))}
            </div>

            <div style={{...styles.iaCard, borderLeftColor: '#3182ce', marginTop: '20px'}}>
              <h4>📋 Nota de Auxílio Médico</h4>
              <p style={{margin: 0}}>Na sexta-feira houve um pico de 4 microdespertares por apineia associado a uma queda na eficiência de sono profundo (5.8h). Este relatório está salvo e consolidado para sua próxima avaliação clínica presencial ou via telemedicina.</p>
            </div>
          </div>
        )}

        {/* PÁGINA 3: NÍVEL DE ESTRESSE */}
        {currentPage === 'estresse' && (
          <div style={styles.fullWidthView}>
            <h2>⚡ Diário de Espírito e Cruzamento de Rotina com IA</h2>
            <p>Informe seus sentimentos. Nossa IA cruzará sua rotina, dados médicos anteriores e métricas de sono para gerar insights preventivos.</p>

            <div style={styles.formSection}>
              <form onSubmit={handleStressSubmit}>
                <div style={{display: 'flex', gap: '20px', marginBottom: '15px', flexWrap: 'wrap'}}>
                  <div style={{flex: 1}}>
                    <label><strong>Como está seu Estado de Espírito hoje?</strong></label>
                    <select style={styles.input} value={userMood} onChange={(e) => setUserMood(e.target.value)}>
                      <option value="Calmo e Disposto">Calmo e Disposto</option>
                      <option value="Cansado / Sobrecarregado">Cansado / Sobrecarregado</option>
                      <option value="Ansioso ou Agitado">Ansioso ou Agitado</option>
                      <option value="Estressado devido ao Trânsito/Rotas">Estressado devido ao Trânsito/Rotas</option>
                    </select>
                  </div>
                </div>

                <label><strong>Relate detalhadamente como foi o seu dia ou situações estressantes:</strong></label>
                <textarea
                  style={styles.textarea}
                  placeholder="Exemplo: Hoje o trânsito nas rotas externas estava pesado e tive poucas pausas para descanso..."
                  value={userStressText}
                  onChange={(e) => setUserStressText(e.target.value)}
                />
                <button type="submit" style={styles.submitButton}>Enviar para Cruzamento da IA</button>
              </form>
            </div>

            {aiStressFeedback && (
              <div style={styles.aiResultBlock}>
                <h3>✨ Diagnóstico de Cruzamento da Inteligência Artificial</h3>
                <p><em>{aiStressFeedback.analise}</em></p>
                <h4 style={{marginBottom: '8px'}}>Atividades e Condutas Recomendadas:</h4>
                <ul>
                  {aiStressFeedback.sugestoes.map((sug, x) => <li key={x} style={{marginBottom: '5px'}}>{sug}</li>)}
                </ul>
              </div>
            )}
          </div>
        )}

        {/* PÁGINA 4: RECOMENDAÇÕES */}
        {currentPage === 'recomendacoes' && (
          <div style={styles.fullWidthView}>
            <h2>📜 Central Unificada de Recomendações Saudáveis (IA)</h2>
            <p>Diretrizes geradas automaticamente cruzando <strong>Batimentos Cardíacos, Monitoramento do Sono, Histórico de Atividades Físicas</strong> e seu <strong>Prontuário Eletrônico</strong>.</p>

            <div style={styles.gridTwoColumns}>
              <div style={styles.iaCard}>
                <h3 style={{color: '#1a5f60', marginTop: 0}}>🍏 Estilo de Vida & Nutrição</h3>
                <p>Baseado no seu prontuário e nos gastos metabólicos das caminhadas ativas, indicamos aumentar o consumo de hidratação fracionada para 3L diários. Adicione alimentos antioxidantes para combater o cansaço muscular do fim de dia.</p>
              </div>
              <div style={{...styles.iaCard, borderLeftColor: '#3182ce'}}>
                <h3 style={{color: '#1a5f60', marginTop: 0}}>💤 Higiene do Sono Sugerida</h3>
                <p>O cruzamento detectou flutuações de batimentos logo após episódios de apineia. Recomendamos manter a cabeceira elevada a 15 graus e evitar telas pretas e smartphones até 45 minutos antes do repouso planejado.</p>
              </div>
            </div>
          </div>
        )}

        {/* PÁGINA 5: AGENDAR CONSULTA */}
        {currentPage === 'agendar' && (
          <div style={styles.fullWidthView}>
            <h2>✍️ Agendamento Unificado na Rede Credenciada</h2>
            <p>Selecione a categoria desejada e reserve seu horário de atendimento humano nas frentes do ecossistema Saúde Para Todos.</p>

            <div style={styles.formSection}>
              <form onSubmit={handleScheduleSubmit} style={{maxWidth: '500px', display: 'flex', flexDirection: 'column', gap: '15px'}}>
                <label>
                  <strong>Selecione o Tipo de Atendimento:</strong>
                  <select style={styles.input} value={newAppointment.tipo} onChange={(e) => setNewAppointment({...newAppointment, tipo: e.target.value})}>
                    <option value="Consulta Geral / Triagem">Consulta Geral / Triagem</option>
                    <option value="Exames Rápidos de Rotina">Exames Rápidos de Rotina</option>
                    <option value="Acompanhamento Preventivo">Acompanhamento Preventivo</option>
                  </select>
                </label>

                <label>
                  <strong>Rede de Saúde Desejada:</strong>
                  <select style={styles.input} value={newAppointment.local} onChange={(e) => setNewAppointment({...newAppointment, local: e.target.value})}>
                    <option value="🚐 Unidades Móveis (Comunidades)">🚐 Unidades Móveis (Comunidades)</option>
                    <option value="🏥 UBS (Unidade Básica de Saúde)">🏥 UBS (Unidade Básica de Saúde)</option>
                    <option value="💻 Telemedicina (Consulta Remota Virtual)">💻 Telemedicina (Consulta Remota Virtual)</option>
                    <option value="🩺 Clínicas e Hospitais Parceiros">🩺 Clínicas e Hospitais Parceiros</option>
                  </select>
                </label>

                <div style={{display: 'flex', gap: '15px'}}>
                  <div style={{flex: 1}}>
                    <label><strong>Data:</strong></label>
                    <input type="date" style={styles.input} value={newAppointment.data} onChange={(e) => setNewAppointment({...newAppointment, data: e.target.value})} />
                  </div>
                  <div style={{flex: 1}}>
                    <label><strong>Horário:</strong></label>
                    <input type="time" style={styles.input} value={newAppointment.hora} onChange={(e) => setNewAppointment({...newAppointment, hora: e.target.value})} />
                  </div>
                </div>

                <button type="submit" style={styles.submitButton}>Confirmar Marcação de Consulta</button>
              </form>
            </div>
          </div>
        )}

        {/* PÁGINA 6: ATIVIDADE FÍSICA */}
        {currentPage === 'atividade' && (
          <div style={styles.fullWidthView}>
            <h2>🏃‍♂️ Sensor de Atividade Física e Métricas em Tempo Real</h2>
            <p>Selecione seu exercício atual. O aplicativo começará o rastreamento ativo de velocidade, distância, passos e relevo geográfico.</p>

            {!activeActivity ? (
              <div style={{display: 'flex', gap: '15px', marginTop: '20px', flexWrap: 'wrap'}}>
                <button style={{...styles.activitySelectBtn, backgroundColor: '#3182ce'}} onClick={() => startPhysicalActivity('Caminhada')}>🚶‍♂️ Iniciar Caminhada</button>
                <button style={{...styles.activitySelectBtn, backgroundColor: '#e53e3e'}} onClick={() => startPhysicalActivity('Corrida')}>🏃‍♂️ Iniciar Corrida</button>
                <button style={{...styles.activitySelectBtn, backgroundColor: '#319795'}} onClick={() => startPhysicalActivity('Ciclismo')}>🚴‍♂️ Iniciar Ciclismo</button>
              </div>
            ) : (
              <div style={styles.activityTrackingPanel}>
                <div style={styles.liveBadgeAnimated}>🔴 MONITORAMENTO ATIVO: {activeActivity.toUpperCase()}</div>

                <div style={styles.gridStats}>
                  {activeActivity !== 'Ciclismo' && (
                    <div style={styles.statBox}>
                      <span style={styles.statLabel}>Passos Calculados</span>
                      <span style={styles.statValue}>{activityStats.passos}</span>
                    </div>
                  )}
                  <div style={styles.statBox}>
                    <span style={styles.statLabel}>Distância Percorrida</span>
                    <span style={styles.statValue}>{activityStats.distancia} <small style={{fontSize: '14px'}}>km</small></span>
                  </div>
                  <div style={styles.statBox}>
                    <span style={styles.statLabel}>Velocidade Atual</span>
                    <span style={styles.statValue}>{activityStats.velocidade} <small style={{fontSize: '14px'}}>km/h</small></span>
                  </div>
                  <div style={styles.statBox}>
                    <span style={styles.statLabel}>Velocidade Média</span>
                    <span style={styles.statValue}>{activityStats.velMedia} <small style={{fontSize: '14px'}}>km/h</small></span>
                  </div>
                  <div style={styles.statBox}>
                    <span style={styles.statLabel}>Relevo Detectado</span>
                    <span style={{...styles.statValue, fontSize: '20px', color: '#1a5f60'}}>{activityStats.relevo}</span>
                  </div>
                </div>

                <button style={styles.stopActivityBtn} onClick={stopPhysicalActivity}>⏹ Finalizar e Salvar Exercício</button>
              </div>
            )}
          </div>
        )}

        {/* PÁGINA 7: EMERGÊNCIA */}
        {currentPage === 'emergencia' && (
          <div style={styles.fullWidthView}>
            <h2>🚨 Central Telefônica de Emergência e Proteção</h2>
            <p>Toque diretamente sobre o serviço necessário para realizar chamadas automáticas de urgência.</p>

            <div style={styles.emergencyGrid}>
              <div style={{...styles.emergencyItem, backgroundColor: '#fff5f5', borderColor: '#feb2b2'}}>
                <div><h3>🚑 SAMU</h3><p style={{fontSize: '20px', fontWeight: 'bold', margin: '4px 0'}}>192</p></div>
                <button style={styles.callBtn} onClick={() => alert("Discando 192...")}>Discar</button>
              </div>
              <div style={{...styles.emergencyItem, backgroundColor: '#fff5f5', borderColor: '#feb2b2'}}>
                <div><h3>🔥 Bombeiros</h3><p style={{fontSize: '20px', fontWeight: 'bold', margin: '4px 0'}}>193</p></div>
                <button style={styles.callBtn} onClick={() => alert("Discando 193...")}>Discar</button>
              </div>
              <div style={{...styles.emergencyItem, backgroundColor: '#fff5f5', borderColor: '#feb2b2'}}>
                <div><h3>🚔 Polícia Militar</h3><p style={{fontSize: '20px', fontWeight: 'bold', margin: '4px 0'}}>190</p></div>
                <button style={styles.callBtn} onClick={() => alert("Discando 190...")}>Discar</button>
              </div>
            </div>

            <h3 style={{marginTop: '30px', color: '#1a5f60'}}>📋 Seus Contatos Pessoais de Confiança Cadastrados</h3>
            <div style={{display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '10px'}}>
              <div style={styles.unitItem}><span><strong>Contato 1:</strong> Ana (Parceira)</span><strong>(81) 99999-5555</strong></div>
              <div style={styles.unitItem}><span><strong>Contato 2:</strong> Pronto Atendimento Central Recife</span><strong>(81) 3184-4100</strong></div>
              <div style={styles.unitItem}><span><strong>Contato 3:</strong> Unidade de Apoio Comunitário</span><strong>0800 281 0100</strong></div>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

